using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking Change 1: EF Core 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so we must explicitly preserve it.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking Change 2: EF Core 9 uses only the raw key for the id property
            // (e.g. "1") instead of "Blog|1". Preserve the old format for existing data.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .ToJsonProperty("id")
                .HasValueGenerator<LegacyIdValueGenerator>();

            // Breaking Change 3: Cosmos DB does not support indexes defined via EF Core
            // HasIndex. In EF 9 this now throws by default instead of being silently ignored.
            entity.HasIndex(b => b.Name);
        });

        // Fix for Breaking Change 3: Suppress the exception for unmapped indexes.
        modelBuilder.Entity<Blog>().Metadata.GetIndexes().ToList().ForEach(i =>
            i.SetIsUnique(null));
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.ConfigureWarnings(w =>
            w.Ignore(Microsoft.EntityFrameworkCore.Diagnostics.CosmosEventId.NoPartitionKeyDefined));
    }
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

